(7307369, 1140120, 37858, '<td valign="top">Made me smile.  Perfect for winter weather.</td>', 'Made me smile.  Perfect for winter weather.', '2015-01-28 02:22:16.000000', NULL, 1),
(7307371, 1140111, 37858, '<td valign="top">Her body language says it all.  Been there; done that.  Nice technicals too, although the focus fall-off at her fingers is something I might not do in an image where her fingers are so critical to the notion of getting warm from the cup she is holding.</td>', 'Her body language says it all.  Been there; done that.  Nice technicals too, although the focus fall-off at her fingers is something I might not do in an image where her fingers are so critical to the notion of getting warm from the cup she is holding.', '2015-01-28 02:25:04.000000', NULL, 1),
